import threading

n = int(input())
元素 = []
for _ in range(n):
    元素.append(int(input()))

结果 = [0] * n


def 翻倍(序号, 数):
    结果[序号] = 数 * 2


对象 = []
for i in range(n):
    一个对象 = threading.Thread(target=翻倍, args=(i, 元素[i]))
    对象.append(一个对象)

for 一个对象 in 对象:
    一个对象.start()

for 一个对象 in 对象:
    一个对象.join()

for 一个数 in 结果:
    print(一个数)
